    """Parses a JSON string into Python objects using a recursive, token-based approach."""

    pos = 0
    length = len(s)

    def next_char():
        nonlocal pos
        if pos < length:
            char = s[pos]
            pos += 1
            return char
        return None

    def skip_whitespace():
        while pos < length and s[pos].isspace():
            next_char()

    def parse_value():
        skip_whitespace()
        char = next_char()

        if char == '"':
            return parse_string()
        elif char.isdigit() or (char == '-' and s[pos].isdigit()):
            return parse_number(char)
        elif char == 't':
            return parse_literal("true", True)
        elif char == 'f':
            return parse_literal("false", False)
        elif char == 'n':
            return parse_literal("null", None)
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        else:
            raise ValueError(f"Unexpected character: {char}")

    def parse_string():
        result = ""
        while True:
            char = next_char()
            if char == '"':
                return result
            elif char == '\\':
                escape_char = next_char()
                if escape_char in '"\\/bfnrt':
                    result += {
                        '"': '"',
                        '\\': '\\',
                        '/': '/',
                        'b': '\b',
                        'f': '\f',
                        'n': '\n',
                        'r': '\r',
                        't': '\t'
                    }[escape_char]
                else:
                    raise ValueError(f"Invalid escape character: {escape_char}")
            else:
                result += char

    def parse_number(first_char):
        number_str = first_char
        char = next_char()
        while char is not None and (char.isdigit() or char in '.-+eE'):
            number_str += char
            char = next_char()
        pos -= 1  # Backtrack to the last character not consumed
        try:
            if '.' in number_str or 'e' in number_str or 'E' in number_str:
                return float(number_str)
            return int(number_str)
        except ValueError:
            raise ValueError(f"Invalid number: {number_str}")

    def parse_literal(expected, value):
        for char in expected:
            if next_char() != char:
                raise ValueError(f"Expected '{expected}'")
        return value

    def parse_array():
        result = []
        skip_whitespace()
        if s[pos] == ']':
            next_char()
            return result
        while True:
            result.append(parse_value())
            skip_whitespace()
            char = next_char()
            if char == ']':
                return result
            elif char != ',':
                raise ValueError(f"Expected ',' or ']', got: {char}")

    def parse_object():
        result = {}
        skip_whitespace()
        if s[pos] == '}':
            next_char()
            return result
        while True:
            key = parse_string()
            skip_whitespace()
            if next_char() != ':':
                raise ValueError("Expected ':' after key")
            value = parse_value()
            result[key] = value
            skip_whitespace()
            char = next_char()
            if char == '}':
                return result
            elif char != ',':
                raise ValueError(f"Expected ',' or '}', got: {char}")

    return parse_value()

